reference:
graph {
    direction: down
    node begin: "Begin" { shape: start }
    node valid: "Valid input?" { shape: diamond }
    node process: "Process" { shape: rounded }
    node reject: "Reject"
    node db: "Results DB" { shape: cylinder }
    node done: "Done" { shape: end }
    begin -> valid
    valid -> process: "yes"
    valid -> reject: "no"
    process -> db: "save"
    process -> process: "retry"
    db -> done
    reject -> done
}

graph {
    direction: left
    node user: "User"
    container cloud: "Cloud" {
        container west: "Region West" {
            container zone: "Zone A" {
                node web: "Web Server"
                node cache: "Cache"
                web -> cache: "lookup"
            }
        }
    }
    user -> cloud.west.zone.web: "HTTPS"
}

graph {
    direction: down
    container frontend: "Frontend" {
        node router: "Router"
        node view: "View"
        router -> view
    }
    container backend: "Backend" {
        node api: "API"
        container storage: "Storage" {
            node pg: "Postgres" { shape: cylinder }
            node blob: "Blob Store" { shape: cylinder }
        }
        api -> storage.pg: "SQL"
        api -> storage.blob: "PUT"
    }
    frontend.view -> backend.api: "fetch"
}

graph {
    direction: up
    node start: "Start" { shape: start }
    node load: "Load Config"
    container pipeline: "Pipeline" {
        container build: "Stage: Build" {
            node compile: "Compile"
            node link: "Link"
            compile -> link: "objects"
            link -> link: "relink"
        }
    }
    node finish: "Finish" { shape: end }
    start -> load
    load -> pipeline.build.compile
    pipeline.build.link -> finish
}
